  ["/bg idioma  el idioma del addon (auto, es, en, de, fr, it, pt, ru)"] = "/bg idioma  la langue de l'addon (auto, es, en, de, fr, it, pt, ru)",
  ["/bg marcas  muestra u oculta las marcas sobre los nombres y en el chat"] = "/bg marcas  affiche ou cache les marques sur les noms et dans le chat",
