  ["Aciertan: %s. ¡Enhorabuena!"] = "Gagnants : %s. Félicitations !",
  ["Activos esta semana"] = "Actifs cette semaine",
  ["Administración"] = "Administration",
  ["Administración enseña cómo va la conexión, con una prueba de mensajes."] = "L'Administration montre l'état de la connexion, avec un test de messages.",
  ["Administración: al cambiar de idioma ya no sale «Una acción de interfaz ha fallado por culpa de un accesorio». El juego no deja que un accesorio recargue la interfaz: escribe /reload."] = "Administration : changer de langue n'affiche plus «Échec d'une action d'interface à cause d'un AddOn». Le jeu ne laisse pas un addon recharger l'interface : tape /reload.",
  ["Ahora no"] = "Pas maintenant",
  ["Ahora no hay nadie más de la hermandad conectado. Cuando haya alguien, sale aquí; si tiene BlazonGuild, con «Retar»."] = "Personne d'autre de la guilde n'est connecté pour l'instant. Quand il y aura quelqu'un, il apparaîtra ici ; avec BlazonGuild, avec «Défier».",
  ["Ahora no puede"] = "Ne peut pas maintenant",
  ["Ahora organizas en %s"] = "Tu organises maintenant dans %s",
  ["Ahora pulsa dónde va %s: un grupo, «Sin grupo» o «Reserva». Si pulsas a otro jugador, se cambian el sitio."] = "Clique maintenant où va %s : un groupe, «Sans groupe» ou «Réserve». Si tu cliques sur un autre joueur, ils échangent leur place.",
  ["Ahora tienen %s conectados, %s con BlazonGuild."] = "Ils ont maintenant %s connectés, %s avec BlazonGuild.",
  ["Ahora: %d %s y %d %s."] = "Maintenant : %d %s et %d %s.",
  ["Ajustes del maestro"] = "Réglages du maître de guilde",
  ["Al abrir el mapa del mundo la ventana se minimiza sola, y vuelve al cerrarlo."] = "Quand tu ouvres la carte du monde, la fenêtre se réduit toute seule et revient quand tu la fermes.",
  ["Al hablar con un posadero, un aviso te propone una partida. Todo por puntos: aquí no se mueve oro."] = "Quand tu parles à un aubergiste, un avis te propose une partie. Tout aux points : ici, pas d'or.",
  ["Al sortear, los mejores de la Arena son cabezas de serie; el resto se sortea con /roll, que veréis en el chat."] = "Au tirage, les meilleurs de l'Arène sont têtes de série ; le reste est tiré au /roll, que vous verrez dans le chat.",
  ["Al terminar, quien la dirigió escribe cómo fue. Queda en la crónica de la hermandad con quién estuvo."] = "À la fin, celui qui l'a dirigée écrit comment ça s'est passé. Cela reste dans la chronique de la guilde avec qui était là.",
  ["Al terminar, quien la dirigió escribe el parte, que queda en la crónica."] = "À la fin, celui qui l'a dirigée écrit le rapport, qui reste dans la chronique.",
  ["Alguien"] = "Quelqu'un",
  ["Alianza"] = "Alliance",
  ["Alianza creada"] = "Alliance créée",
  ["Alianza «%s»"] = "Alliance «%s»",
  ["Alianza, pestaña «Cartas y avisos»: cartas del líder a los maestros (con quién las ha leído), «puertas abiertas» para mandar a los nuevos a una hermandad y ocultar a alguien en los chats comunes."] = "Alliance, onglet «Lettres et avis» : lettres du chef aux maîtres (avec qui les a lues), «portes ouvertes» pour envoyer les nouveaux à une guilde, et masquer quelqu'un dans les discussions communes.",
  ["Alter de %s"] = "Reroll de %s",
  ["Anillo"] = "Anneau",
  ["Anotado por %s el %s."] = "Noté par %s le %s.",
  ["Anotar"] = "Noter",
  ["Anotar botín"] = "Noter le butin",
  ["Antes acepta la privacidad: sin eso el addon no envía nada."] = "Accepte d'abord la confidentialité : sans cela, l'addon n'envoie rien.",
