  ["Apuntados (%s de %s): %s."] = "Inscrits (%s sur %s) : %s.",
  ["Apuntar a mano"] = "Noter à la main",
  ["Apuntar en el libro"] = "Noter dans le registre",
  ["Apuntar en la Tesorería el oro del correo (solo lee lo que hace el juego)"] = "Noter dans la trésorerie l'or du courrier (il lit seulement ce que fait le jeu)",
  ["Apuntar mis muertes y bajas: no"] = "Noter mes morts et mes victimes : non",
  ["Apuntar mis muertes y bajas: sí"] = "Noter mes morts et mes victimes : oui",
  ["Apuntarme"] = "M'inscrire",
  ["Aquí no hay capas: estás en una mazmorra, en un barco o volando."] = "Il n'y a pas de couches ici : tu es dans un donjon, sur un bateau ou en vol.",
  ["Aquí no hay zona: estás en una mazmorra, en un barco o volando."] = "Pas de zone ici : tu es dans un donjon, sur un bateau ou en vol.",
  ["Aquí tendréis una pestaña por cada hermandad hermana."] = "Ici, vous aurez un onglet par guilde sœur.",
  ["Arena"] = "Arène",
  ["Arena, nueva pestaña «Taberna»: los Huesos, un juego de dados por puntos (contra la casa para practicar, o contra alguien de la hermandad)."] = "Arène, nouvel onglet «Taverne» : les Osselets, un jeu de dés aux points (contre la maison pour s'entraîner, ou contre quelqu'un de la guilde).",
  ["Arena, nueva pestaña «Torneos»: torneos con cuadro eliminatorio y sorteo con /roll, y veladas con combates anunciados."] = "Arène, nouvel onglet «Tournois» : tournois à élimination directe avec tirage au /roll, et soirées de combats annoncés.",
  ["Arena, «Cara a cara»: dos luchadores frente a frente (puntos, rango, récord, sus combates entre ellos), con su vida en directo si los tienes cerca y quién gana al acabar. Se agranda para retransmitir."] = "Arène, «Face-à-face» : deux combattants côte à côte (points, rang, bilan, leurs combats entre eux), avec leur vie en direct s'ils sont près de toi et le gagnant à la fin. S'agrandit pour diffuser.",
  ["Arena: %s"] = "Arène : %s",
  ["Arena: en «Retos» salen todos los conectados, y se explica cómo retar. Administración: solo marca en rojo los errores de esta versión."] = "Arène : «Défis» montre tous les connectés et explique comment défier. Administration : seules les erreurs de cette version sont en rouge.",
  ["Armería"] = "Armurerie",
  ["Armería: cada objeto sale con su nombre y su icono (antes salía «Objeto 6189» con una interrogación). En tu propio equipo, la ventana del objeto ya no sale repetida al lado."] = "Armurerie : chaque objet affiche son nom et son icône (avant, on voyait «Objet 6189» avec un point d'interrogation). Sur ton propre équipement, la fenêtre de l'objet n'apparaît plus en double.",
  ["Armería: la lista del equipo ya no se sale de su panel la primera vez que se abre."] = "Armurerie : la liste de l'équipement ne dépasse plus de son panneau à la première ouverture.",
  ["Armería: «Ver su equipo» funciona aunque esté lejos (si tiene BlazonGuild, se lo pedimos). Y en los encargos puedes poner el objeto con Mayús+clic o arrastrándolo."] = "Armurerie : «Voir son équipement» marche même de loin (s'il a BlazonGuild, on le lui demande). Et dans les commandes tu peux mettre l'objet par Maj+clic ou en le glissant.",
  ["Arrastra aquí a quien quede de reserva."] = "Glisse ici ceux qui restent en réserve.",
  ["Arrastra cada nombre a su grupo y su fila, o púlsalo y luego pulsa dónde va. Al soltarlo sobre otro, se cambian el sitio."] = "Glisse chaque nom dans son groupe et sa ligne, ou clique dessus puis là où il va. En le lâchant sur quelqu'un, ils échangent leur place.",
  ["Arreglado: Artesanía y botín se veía con las pestañas una encima de otra."] = "Corrigé : Artisanat et butin affichait ses onglets les uns sur les autres.",
  ["Arreglado: al volver a programar una raid cancelada, seguía cancelada."] = "Corrigé : reprogrammer un raid annulé le laissait annulé.",
  ["Arreglado: la Arena y «Se busca» se quedaban a medias (y la Arena enseñaba «Nueva temporada» a todos)."] = "Corrigé : l'Arène et «Recherchés» s'arrêtaient à mi-chemin (et l'Arène montrait «Nouvelle saison» à tous).",
  ["Arrástralo a un grupo, o púlsalo y luego pulsa dónde va. Clic derecho: sin grupo."] = "Glisse-le dans un groupe, ou clique dessus puis là où il va. Clic droit : sans groupe.",
  ["Arrástralo para moverlo por el borde del minimapa. /bg minimapa lo oculta."] = "Glisse-le pour le déplacer autour de la minicarte. /bg minimapa le cache.",
  ["Artesanos"] = "Artisans",
  ["Artesanos de la hermandad"] = "Artisans de la guilde",
  ["Artesanía y botín"] = "Artisanat et butin",
  ["Asalto"] = "Assaut",
