  ["Así funciona la Alianza"] = "Comment fonctionne l'Alliance",
  ["Así funciona la Arena"] = "Comment fonctionne l'Arène",
  ["Así funciona la Sala de guerra"] = "Comment fonctionne la Salle de guerre",
