  ["Así funciona «Se busca»"] = "Comment fonctionne «Recherchés»",
  ["Así funcionan las Raids"] = "Comment fonctionnent les raids",
  ["Así funcionan los honores"] = "Comment fonctionnent les honneurs",
  ["Así tu hermandad te ve en la Armería aunque estéis lejos: lo que llevas puesto y su nivel, lo mismo que ve quien te inspecciona en el juego."] = "Ainsi ta guilde te voit dans l'Armurerie même de loin : ce que tu portes et son niveau, comme le voit quiconque t'inspecte dans le jeu.",
  ["Ausente"] = "Absent",
  ["Automático (el del juego)"] = "Automatique (celle du jeu)",
  ["Autoprueba"] = "Autotest",
  ["Autoprueba (Administración o /bg autoprueba): comprueba el addon en tu juego y te da un informe para copiar."] = "Autotest (Administration ou /bg autoprueba) : vérifie l'addon dans ton jeu et te donne un rapport à copier.",
  ["Avisamos a %s. En cuanto contesten, estaréis dentro."] = "Nous avons prévenu %s. Dès qu'ils répondent, vous serez dedans.",
  ["Avisamos a todos los llamados de que no se hace."] = "Nous prévenons tous les appelés que cela n'a pas lieu.",
  ["Aviso final"] = "Dernier avertissement",
  ["Avisos %s"] = "Avertissements %s",
  ["Avisos acumulados: %s de 3. Al tercero se abre un caso que decide el maestro."] = "Avertissements cumulés : %s sur 3. Au troisième, un dossier est ouvert et le maître de guilde décide.",
  ["Avistamiento: %s"] = "Observation : %s",
  ["Avistamientos"] = "Observations",
  ["Ayuda"] = "Aide",
  ["Azshara"] = "Azshara",
  ["Añade antes algún combate."] = "Ajoute d'abord un combat.",
  ["Añadir"] = "Ajouter",
  ["Añadir combate"] = "Ajouter un combat",
  ["Añadir un combate a la velada"] = "Ajouter un combat à la soirée",
  ["Aún nadie"] = "Personne pour l'instant",
  ["Aún nadie ha cazado a un buscado."] = "Personne n'a encore chassé de recherché.",
  ["Aún nadie ha jugado una partida entre miembros. Las de práctica contra la casa no cuentan."] = "Personne n'a encore joué de partie entre membres. Les parties d'entraînement contre la maison ne comptent pas.",
  ["Aún nadie ha votado. "] = "Personne n'a encore voté. ",
  ["Aún nadie, aparte del jefe."] = "Personne pour l'instant, à part le chef.",
  ["Aún nadie."] = "Personne pour l'instant.",
  ["Aún nadie. Cuando alguien entra, dice quién le trajo."] = "Personne pour l'instant. Quand quelqu'un arrive, il dit qui l'a amené.",
  ["Aún ninguna. Aquí salen las raids de BlazonGuild que ya empezaron, con cuántos fueron."] = "Aucun pour l'instant. Ici apparaissent les raids BlazonGuild déjà commencés, avec combien y sont allés.",
  ["Aún ninguno. Cuando la hermandad mate a un jefe de esta banda (con la mayoría del grupo de la hermandad), el addon de quien estaba allí lo apunta solo."] = "Aucun pour l'instant. Quand la guilde tue un boss de ce raid (avec un groupe surtout de la guilde), l'addon de quelqu'un qui était là le note tout seul.",
  ["Aún no compartes tu equipo. Pulsa «Compartir mi equipo» y tu hermandad verá lo que llevas puesto (se actualiza solo cuando cambias algo)."] = "Tu ne partages pas encore ton équipement. Clique sur «Partager mon équipement» et ta guilde verra ce que tu portes (ça se met à jour tout seul quand tu changes quelque chose).",
  ["Aún no conocéis ninguna hermandad. Cuando alguien de la vuestra juegue en grupo con alguien de otra hermandad que use BlazonGuild y publique sus cifras, aparecerá aquí."] = "Vous ne connaissez encore aucune guilde. Quand quelqu'un de la vôtre jouera en groupe avec quelqu'un d'une autre guilde qui utilise BlazonGuild et publie ses chiffres, elle apparaîtra ici.",
  ["Aún no conocéis otras hermandades. Aparecen al jugar en grupo (mazmorras, bandas, campos de batalla) con alguien de ellas que use BlazonGuild."] = "Vous ne connaissez pas encore d'autres guildes. Elles apparaissent quand vous jouez en groupe (donjons, raids, champs de bataille) avec quelqu'un de chez elles qui utilise BlazonGuild.",
  ["Aún no ha pasado nada. Aquí sale cada muerte y cada baja que apuntan los miembros con el addon."] = "Rien ne s'est encore passé. Ici apparaît chaque mort et chaque victime que notent les membres avec l'addon.",
  ["Aún no ha peleado esta temporada."] = "N'a pas encore combattu cette saison.",
  ["Aún no ha respondido nadie."] = "Personne n'a encore répondu.",
  ["Aún no has preguntado nada."] = "Tu n'as encore rien demandé.",
  ["Aún no hay campeón: el primero que gane un duelo se lleva el cinturón."] = "Pas encore de champion : le premier à gagner un duel prend la ceinture.",
  ["Aún no hay cartas. El líder de la alianza escribe aquí a los maestros (y, si quiere, a los capitanes)."] = "Pas encore de lettres. Le chef de l'alliance écrit ici aux maîtres (et, s'il veut, aux capitaines).",
  ["Aún no hay combates esta temporada."] = "Pas encore de combats cette saison.",
  ["Aún no hay combates esta temporada. Reta a alguien en «Retos», o batíos en duelo desde el juego: el addon de quien pierde lo apunta solo."] = "Pas encore de combats cette saison. Défie quelqu'un dans «Défis», ou battez-vous en duel dans le jeu : l'addon du perdant le note tout seul.",
  ["Aún no hay combates.%s"] = "Pas encore de combats.%s",
  ["Aún no hay escuadras. "] = "Pas encore d'escouades. ",
  ["Aún no hay escuadras. Crea una con un jefe y unos pocos miembros: tendrá su propio chat y podréis llamarla a operaciones."] = "Pas encore d'escouades. Crée-en une avec un chef et quelques membres : elle aura son propre chat et vous pourrez l'appeler en opération.",
  ["Aún no hay escuadras. Las crean los organizadores; cada una tiene su jefe y su propio chat."] = "Pas encore d'escouades. Les organisateurs les créent ; chacune a son chef et son propre chat.",
  ["Aún no hay ficha. La escriben los oficiales: a qué os dedicáis, idioma, días de banda y a quién buscáis."] = "Pas encore de fiche. Les officiers l'écrivent : ce que vous faites, la langue, les jours de raid et qui vous cherchez.",
  ["Aún no hay foto del banco. Aparecerá cuando un oficial o un tesorero lo abra con BlazonGuild."] = "Pas encore de photo de la banque. Elle apparaîtra quand un officier ou un trésorier l'ouvrira avec BlazonGuild.",
  ["Aún no hay nadie en este ranking."] = "Personne dans ce classement pour l'instant.",
  ["Aún no hay nadie. Para salir aquí, cada uno abre la ventana de su profesión en el juego y dice «Publicar». Escribe arriba un objeto para buscar quién lo fabrica."] = "Personne pour l'instant. Pour apparaître ici, chacun ouvre la fenêtre de son métier dans le jeu et dit «Publier». Tape un objet en haut pour trouver qui le fabrique.",
  ["Aún no hay ningún cargo."] = "Aucune charge pour l'instant.",
  ["Aún no hay partes. Quien dirige una operación lo escribe al terminarla."] = "Pas encore de rapports. Celui qui dirige une opération l'écrit à la fin.",
  ["Aún no hay tesoreros: los nombra el maestro en «Cuotas». "] = "Pas encore de trésoriers : le maître de guilde les nomme dans «Cotisations». ",
  ["Aún no hay torneos. Cualquiera puede crear uno con «Nuevo»: un torneo con cuadro eliminatorio, o una velada con combates anunciados."] = "Pas encore de tournois. Tout le monde peut en créer un avec «Nouveau» : un tournoi à élimination directe, ou une soirée de combats annoncés.",
  ["Aún no hemos visto ninguna. En el juego, abre la ventana de tu profesión (por ejemplo, Herrería o Alquimia): BlazonGuild te preguntará si quieres publicarla. Solo la ve tu hermandad."] = "Nous n'en avons encore vu aucun. Dans le jeu, ouvre la fenêtre de ton métier (par exemple Forge ou Alchimie) : BlazonGuild te demandera si tu veux la publier. Seule ta guilde la voit.",
  ["Aún no se sabe qué lleva."] = "On ne sait pas encore ce qu'il porte.",
  ["Aún no tienes boletos hoy."] = "Tu n'as pas encore de billets aujourd'hui.",
  ["Aún no tienes honores. Cazar buscados, donar, fabricar encargos, traer gente o ir a las raids te sube en los rankings."] = "Tu n'as pas encore d'honneurs. Chasser des recherchés, donner, fabriquer des commandes, amener des gens ou aller en raid te fait monter dans les classements.",
  ["Aún sin combates esta temporada."] = "Pas encore de combats cette saison.",
  ["Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Pas encore de contact : il viendra quand quelqu'un des leurs se connectera avec BlazonGuild.",
