  ["Bastión Krol'dok"] = "Krol'dok Stronghold",
  ["Batíos en duelo desde el juego (clic derecho en su retrato, «Duelo»). Al terminar, el juego dice quién ganó, y el addon de quien pierde lo apunta solo."] = "Battez-vous en duel dans le jeu (clic droit sur son portrait, «Duel»). À la fin, le jeu dit qui a gagné, et l'addon du perdant le note tout seul.",
  ["BlazonGuild %s; juego %s, interfaz %s"] = "BlazonGuild %s ; jeu %s, interface %s",
  ["BlazonGuild deja de tocar los menús, las placas y el chat del juego. Su ventana sigue igual."] = "BlazonGuild ne touche plus aux menus, aux barres de nom ni à la discussion du jeu. Sa fenêtre reste la même.",
  ["BlazonGuild está listo"] = "BlazonGuild est prêt",
  ["BlazonGuild funciona entre los addons de los miembros de tu hermandad. Para eso, tu addon tiene que mandar algunos datos a los de tus compañeros. Si aceptas, esto es lo que se comparte:"] = "BlazonGuild fonctionne entre les addons des membres de ta guilde. Pour cela, ton addon doit envoyer quelques données à ceux de tes compagnons. Si tu acceptes, voici ce qui est partagé :",
  ["BlazonGuild habla ahora inglés, alemán, francés, italiano, portugués y ruso, además de español."] = "BlazonGuild parle maintenant anglais, allemand, français, italien, portugais et russe, en plus de l'espagnol.",
  ["BlazonGuild vuelve a poner sus marcas y sus líneas en la interfaz del juego."] = "BlazonGuild remet ses marques et ses lignes dans l'interface du jeu.",
  ["BlazonGuild — autoprueba %s"] = "BlazonGuild — autotest %s",
  ["Borrar"] = "Supprimer",
