  ["Botín de las bandas"] = "Butin des raids",
  ["Botón para minimizar (junto a la X): queda una barra pequeña que puedes mover; púlsala para volver."] = "Bouton pour réduire (à côté du X) : il reste une petite barre que tu peux déplacer ; clique dessus pour revenir.",
  ["Bronce"] = "Bronze",
  ["Brujo"] = "Démoniste",
  ["Busca antes la hermandad: hace falta alguien suyo conectado."] = "Cherche d'abord la guilde : il faut quelqu'un des leurs connecté.",
  ["Busca grupo%s como %s"] = "Cherche un groupe%s en tant que %s",
  ["Busca quién fabrica algo"] = "Trouve qui fabrique quelque chose",
  ["Busca quién sabe hacer un objeto, susúrrale o hazle un encargo; los encargos cumplidos hacen el ranking de artesanos."] = "Trouve qui sait faire un objet, chuchote-lui ou passe-lui une commande ; les commandes livrées font le classement des artisans.",
  ["Busca un objeto arriba para ver qué sabe hacer, o pulsa «Pedir» para hacerle un encargo."] = "Cherche un objet en haut pour voir ce qu'il sait faire, ou clique sur «Commander» pour lui passer une commande.",
  ["Busca una hermandad y pulsa «Ver su ficha» en alguien suyo."] = "Cherche une guilde et clique sur «Voir sa fiche» chez quelqu'un des leurs.",
  ["Buscamos "] = "Nous cherchons ",
  ["Buscamos %s"] = "Nous cherchons %s",
  ["Buscan grupo"] = "Cherchent un groupe",
  ["Buscando… (el juego también abre su lista de /who; puedes cerrarla)"] = "Recherche… (le jeu ouvre aussi sa liste /who ; tu peux la fermer)",
  ["Buscar"] = "Chercher",
  ["Buscar grupo"] = "Chercher un groupe",
  ["Buscar por persona u objeto"] = "Chercher par personne ou objet",
  ["Buscar una hermandad"] = "Chercher une guilde",
  ["Buscas grupo: %s, como %s. Toda la hermandad lo ve. Se quita sola en %s min."] = "Tu cherches un groupe : %s, en tant que %s. Toute la guilde le voit. Cela disparaît tout seul dans %s min.",
  ["Búscale%s y retadle desde el juego: clic derecho en su retrato, «Duelo»."] = "Trouve-le%s et défie-le dans le jeu : clic droit sur son portrait, «Duel».",
  ["Cabeza"] = "Tête",
  ["Cada combate lo decide el duelo entre los dos, y toda la hermandad se entera de quién pasa y de quién gana."] = "Chaque combat est décidé par le duel entre les deux, et toute la guilde apprend qui passe et qui gagne.",
  ["Cada día, hasta %s boletos gratis: un número del 1 al 100 cada uno. Un oficial sortea con /roll 1-100."] = "Chaque jour, jusqu'à %s billets gratuits : un nombre de 1 à 100 chacun. Un officier tire avec /roll 1-100.",
  ["Cada hermandad sigue con su maestro y sus normas; podéis salir cuando quieras."] = "Chaque guilde garde son maître et ses règles ; vous pouvez partir quand vous voulez.",
  ["Cada hermandad sigue con su maestro. La alianza tiene un líder: el maestro de la hermandad que vote más de la mitad de los maestros (si no, la fundadora)."] = "Chaque guilde garde son maître. L'alliance a un chef : le maître de la guilde que vote plus de la moitié des maîtres (sinon, la fondatrice).",
  ["Cada maestro nombra capitanes (entran en «Oficiales de la alianza») y mensajeros."] = "Chaque maître nomme des capitaines (ils entrent dans «Officiers de l'alliance») et des messagers.",
  ["Cada maestro vota a una hermandad. Lidera la que tenga más de la mitad de los votos; si ninguna, la fundadora."] = "Chaque maître vote pour une guilde. Celle qui a plus de la moitié des votes dirige ; sinon, la fondatrice.",
  ["Cada miembro que mata le suma 1 de recompensa; 2 si le sacaba 10 niveles o más. Por ejemplo: mata a tres de los vuestros y su recompensa es 3."] = "Chaque membre qu'il tue ajoute 1 à sa prime ; 2 s'il avait 10 niveaux ou plus de plus. Par exemple : il tue trois des vôtres et sa prime est de 3.",
  ["Cada muerte de un miembro suma 1 a la recompensa del que le mató (2 si le sacaba 10 niveles o más). Quien le mate se lleva la recompensa más 1 punto, y la recompensa vuelve a cero."] = "Chaque mort d'un membre ajoute 1 à la prime de son tueur (2 s'il avait 10 niveaux ou plus de plus). Celui qui le tue remporte la prime plus 1 point, et la prime revient à zéro.",
  ["Cada nuevo miembro dice quién le trajo, y sale quién trae más gente a la hermandad."] = "Chaque nouveau membre dit qui l'a amené, et on voit qui amène le plus de monde dans la guilde.",
  ["Cada nuevo miembro dice quién le trajo, y si cambias de hermandad puedes traerte tu ficha."] = "Chaque nouveau membre dit qui l'a amené, et si tu changes de guilde, tu peux emporter ta fiche.",
