  ["La hermandad no sale: pulsa para publicar sus cifras (nada de nadie en concreto). "] = "La guilde n'apparaît pas : clique pour publier ses chiffres (rien sur personne en particulier). ",
  ["La hermandad que lidera escribe cartas a los maestros, dice a qué hermandad van los nuevos y puede ocultar a alguien en los chats comunes. Y en la Sala de guerra, sus operaciones llegan a todas."] = "La guilde qui dirige écrit aux maîtres, dit vers quelle guilde vont les nouveaux et peut masquer quelqu'un dans les discussions communes. Et dans la salle de guerre, ses opérations arrivent à toutes.",
  ["La hermandad que lidera la alianza planea la operación en su Sala de guerra eligiendo «Toda la alianza». Llega a la Sala de guerra de cada hermandad; cada uno responde allí y el líder ve cuántos van de cada una."] = "La guilde qui dirige l'alliance planifie l'opération dans sa salle de guerre en choisissant «Toute l'alliance». Elle arrive dans la salle de guerre de chaque guilde ; chacun y répond et le chef voit combien viennent de chacune.",
  ["La línea de BlazonGuild en el recuadro de un jugador"] = "La ligne BlazonGuild dans l'infobulle d'un joueur",
  ["La mejor puntuación de la Arena de la hermandad."] = "Le meilleur score d'Arène de la guilde.",
  ["La mejor puntuación de la Arena esta temporada, con 5 combates o más."] = "La meilleure cote de l'Arène cette saison, avec 5 combats ou plus.",
  ["La prueba no ha vuelto"] = "Le test n'est pas revenu",
  ["La puntuación"] = "La cote",
  ["La sala de este evento de la Arena, para quien lucha y quien mira. Se cierra una semana después de crearlo."] = "La salle de cet événement de l'Arène, pour ceux qui combattent et ceux qui regardent. Elle ferme une semaine après sa création.",
  ["La semana pasada: "] = "La semaine dernière : ",
  ["La temporada %s se cierra y se guarda con su campeón y su podio."] = "La saison %s se termine et est gardée avec son champion et son podium.",
  ["La ventana de BlazonGuild, sus diálogos y sus avisos"] = "La fenêtre de BlazonGuild, ses dialogues et ses avis",
  ["La ventana «Cara a cara»"] = "La fenêtre «Face-à-face»",
  ["Las Mazmorras"] = "La Prison",
  ["Las Minas de la Muerte"] = "Les Mortemines",
  ["Las capas"] = "Les couches",
  ["Las cartas del líder de la alianza son para los maestros y los capitanes de cada hermandad."] = "Les lettres du chef de l'alliance sont pour les maîtres et les capitaines de chaque guilde.",
  ["Las decisiones finales de moderación siguen siendo del maestro."] = "Les décisions finales de modération restent au maître de guilde.",
  ["Las demás hermandades ya lo saben."] = "Les autres guildes le savent déjà.",
  ["Las hermandades de vuestra facción que juegan con BlazonGuild y publican sus cifras. Se conocen al jugar en grupo con alguien de ellas."] = "Les guildes de votre faction qui jouent avec BlazonGuild et publient leurs chiffres. On les découvre en jouant en groupe avec quelqu'un de chez elles.",
  ["Las hermandades la reciben solas; durante un minuto puede perderse algún mensaje."] = "Les guildes la reçoivent toutes seules ; pendant une minute, un message peut se perdre.",
  ["Las inscripciones ya están cerradas."] = "Les inscriptions sont déjà closes.",
  ["Las listas para elegir a alguien ya no salen vacías: se hacen al abrirlas, y si no hay nadie lo dicen."] = "Les listes pour choisir quelqu'un ne s'ouvrent plus vides : elles se font à l'ouverture, et s'il n'y a personne elles le disent.",
  ["Las marcas"] = "Les marques",
  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "Les marques au-dessus des barres de nom et l'anneau du portrait de la cible",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "Les donjons à l'intérieur d'une capitale sont à sa faction ; les autres sont pour tous (Les Mortemines et le donjon d'Ombrecroc apparaissent maintenant aux deux factions).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "Les donjons et raids sont maintenant ceux de WoW Forever : ses 9 nouveaux donjons (Hall of Thanes, Ruines de Lordaeron, City of Dalaran, Blackmaw Hold…) et ses trois raids, The Barrow Deeps, Sommet d'Hyjal et Repaire d'Onyxia, avec les noms du jeu.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "Les autres guildes n'ont pas encore dit combien viennent.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "Les autres guildes ne te verront pas connecté. Les messages «Maîtres» des autres guildes ne te parviendront pas tant que tu restes caché.",
  ["Las otras hermandades vuelven a verte conectado."] = "Les autres guildes te voient de nouveau connecté.",
  ["Las próximas dos semanas"] = "Les deux prochaines semaines",
  ["Las próximas dos semanas (%s)"] = "Les deux prochaines semaines (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "Les raids sont partagés entre les addons de ta guilde. Pour les créer, les voir et t'inscrire, accepte d'abord la confidentialité.",
  ["Las salas de roles y el comercio se comparten con todas."] = "Les salons de rôles et le commerce sont partagés avec toutes.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "On lui a demandé s'il le partage ; en attente de sa réponse.",
  ["Le toca a %s%s"] = "C'est au tour de %s%s",
  ["Le toca a %s…"] = "C'est au tour de %s…",
  ["Levantar bandera"] = "Lever le drapeau",
  ["Libro"] = "Registre",
  ["Libro de la tesorería"] = "Registre de la trésorerie",
  ["Libro para todos: %s"] = "Registre pour tous : %s",
  ["Liderazgo"] = "Direction",
  ["Llamada a los oficiales"] = "Appel aux officiers",
  ["Llamar a los oficiales"] = "Appeler les officiers",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "C'est arrivé par %s. «Inviter» envoie l'invitation du jeu ; «Non» le lui dit poliment.",
  ["Lleva un tabardo."] = "Porte un tabard.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "Noté par l'addon de %s, qui a perdu : seul le perdant note le combat, pour que personne ne se donne de victoires.",
  ["Lo comparte él mismo (%s)."] = "Il le partage lui-même (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "Il le partage : tu le vois même de loin.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Ceux qui ont l'addon le partagent tout de suite ; pour les autres, cela vient du site via l'appli passerelle.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Les membres avec l'addon le partagent ; pour les autres, Battle.net via le site.",
  ["Lo decide el maestro. Ahora: %s"] = "C'est le maître de guilde qui décide. Maintenant : %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "Leur premier duel décide : clic droit sur le portrait de l'autre, «Duel».",
  ["Lo hace %s."] = "%s s'en charge.",
  ["Lo hago"] = "Je m'en charge",
  ["Lo lleva %s"] = "Détenu par %s",
  ["Lo pide %s. %s%s"] = "Demandé par %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "Tu peux le changer quand tu veux dans l'Armurerie.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "Tu peux l'arrêter quand tu veux dans l'Armurerie («Partager mon équipement»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "Ce que dit n'importe qui dans le chat de guilde, avec ou sans l'addon. Ce qui a été dit pendant ton absence te parvient par un compagnon avec BlazonGuild.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "Ce que le jeu lui-même dit de toi et qui compte pour la guilde : tes duels avec tes compagnons, qui te tue en JcJ hors des donjons, l'or que tu donnes à un trésorier et les boss que vous tuez ensemble.",
  ["Lo que la hermandad debe saber"] = "Ce que la guilde doit savoir",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "Ta guilde voit ce que tu publies : qui sait faire chaque objet, pour te chuchoter ou te passer commande. Cela se met à jour quand tu ouvres le métier.",
  ["Lo que responde aquí"] = "Ce qu'il répond ici",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "Ce que ta guilde publie depuis le jeu pourra aussi être vu sur le site de BlazonGuild.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "Ce que tu fais depuis l'addon : t'inscrire à un raid, publier un groupe, ton profil… Tu décides chaque chose sur le moment.",
  ["Lo verás en la Armería en un momento."] = "Tu le verras dans l'Armurerie dans un instant.",
  ["Lo verás todo en /bg."] = "Tu verras tout dans /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "Vu par le propre client de %s (le récapitulatif de mort du jeu).",
  ["Lo viste tú (%s)."] = "Tu l'as vu (%s).",
  ["Lo último"] = "Le plus récent",
  ["Lo último: %s"] = "Dernier : %s",
  ["Logros"] = "Hauts faits",
  ["Los Baldíos"] = "Les Tarides",
  ["Los Humedales"] = "Les Paluns",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "Les inscrits le verront comme annulé. On peut le reprogrammer en le modifiant.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "Les changements de l'alliance sont signés : personne ne peut les falsifier.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "Les capitaines lisent et écrivent dans «Officiers de l'alliance» ; les messagers portent les messages aux autres guildes. Écris son nom et choisis la charge.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "Les dossiers de modération et les avertissements ne sont plus que sur l'ordinateur des organisateurs.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "Les combats précédents restent enregistrés, mais ne comptent plus.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "Les connectés de chaque zone, avec ou sans BlazonGuild.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "Les liens d'objets du chat s'affichent bien (avant ils étaient cassés), même ceux déjà enregistrés.",
  ["Los grupos"] = "Les groupes",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "Les groupes sont partagés entre les addons de ta guilde. Accepte la confidentialité pour les voir (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "Les boss de raid sont notés même quand le jeu ne donne que le prénom, et le classement des guildes vérifie maintenant les fiches des autres.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "Le chef du raid, celui qui l'a créé et les officiers les déplacent. Tu le vois tel qu'il est.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "Les noms et ce que chacun écrit (notes, annonces, messages) s'affichent tels quels, sans traduction.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "Les officiers notent à qui chaque objet a été donné et pourquoi, pour que le prochain raid parte de ce qui est déjà décidé. Sans enchères ni or.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "Les officiers créent de petites escouades avec leur chef (par exemple «Les Loups», d'assaut). Le chef choisit ses gens ; l'escouade a son propre chat.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "Les officiers de %s le voient déjà. Ils t'inviteront depuis le jeu s'ils disent oui.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "Les officiers écrivent la fiche publique : ce que vous faites, la langue, quand vous jouez et qui vous cherchez (par exemple des soigneurs).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "Les organisateurs de toutes les guildes de l'alliance. Personne d'autre ne le lit.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "Les organisateurs nomment des arbitres dans l'Arène. Un arbitre peut décider à la main des combats de n'importe quel tournoi et retirer un duel noté par erreur.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Les organisateurs peuvent voir l'addon comme un membre («Voir comme un membre»), et d'autres addons peuvent lire BlazonGuild si tu le permets.",
  ["Los puntos de los compañeros en el mapa del mundo"] = "Les points des compagnons sur la carte du monde",
  ["Los puntos del minimapa y la flecha «Seguir»"] = "Les points de la minicarte et la flèche «Suivre»",
  ["Los que guardas valen %d."] = "Ceux que tu gardes valent %d.",
  ["Los rankings"] = "Les classements",
  ["Los tesoreros"] = "Les trésoriers",
  ["Lotería de práctica"] = "Loterie d'entraînement",
  ["Lotería de práctica: cada día, hasta 3 boletos gratis; un oficial sortea con /roll 1-100 y se anuncia quién acierta."] = "Loterie d'entraînement : chaque jour, jusqu'à 3 billets gratuits ; un officier tire avec /roll 1-100 et on annonce qui gagne.",
  ["Lotería: ha salido el %s"] = "Loterie : le %s est sorti",
