  ["Luchador 2"] = "Combattant 2",
  ["Lugar: «%s»"] = "Lieu : «%s»",
  ["Líder: %s, maestro de %s."] = "Chef : %s, maître de %s.",
  ["Maestro: %s. Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Maître de guilde : %s. Pas encore de contact : il viendra quand quelqu'un des leurs se connectera avec BlazonGuild.",
  ["Maestros"] = "Maîtres",
  ["Mago"] = "Mage",
  ["Mano derecha"] = "Main droite",
  ["Mano izquierda"] = "Main gauche",
  ["Manos"] = "Mains",
  ["Mapa"] = "Carte",
  ["Mapa explica qué pasa al compartir tu posición, quién te ve y dónde, y abre el mapa del mundo."] = "La Carte explique ce qui se passe quand tu partages ta position, qui te voit et où, et ouvre la carte du monde.",
  ["Mapa, pestaña «Avistamientos»: pregunta a tu hermandad dónde se vio a un jugador de la otra facción (responde quien lo acepta)."] = "Carte, onglet «Observations» : demande à ta guilde où un joueur de l'autre faction a été vu (répond qui l'accepte).",
  ["Mapa, pestaña «En el mapa»: «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión."] = "Carte, onglet «Sur la carte» : «Suivre» place sous la minicarte une flèche qui te mène à un membre ou au point de réunion.",
  ["Mapa: quien comparte su posición sale ahora también como un punto en tu minimapa."] = "Carte : qui partage sa position apparaît maintenant aussi comme un point sur ta minicarte.",
  ["Maraudon"] = "Maraudon",
  ["Marcar leída"] = "Marquer comme lue",
  ["Marcas en el chat del juego"] = "Marques dans le chat du jeu",
  ["Marcas en nombres y chat: no"] = "Marques sur les noms et le chat : non",
  ["Marcas en nombres y chat: sí"] = "Marques sur les noms et le chat : oui",
  ["Marcas: el escudo sobre los nombres y el aro del retrato de tu objetivo ya no tocan en combate los marcos protegidos del juego, que podían sacar «Las acciones de interfaz han fallado debido a este add-on» en la lista de accesorios."] = "Marques : l'écusson au-dessus des noms et l'anneau du portrait de ta cible ne touchent plus en combat les cadres protégés du jeu, ce qui pouvait faire apparaître le message d'actions d'interface échouées dans la liste des addons.",
  ["Marjal Revolcafango"] = "Marécage d'Âprefange",
  ["Mayor donante"] = "Plus grand donateur",
  ["Mayores donantes (90 días)"] = "Plus grands donateurs (90 jours)",
  ["Mayús + clic en un objeto para ponerlo en un campo de BlazonGuild"] = "Maj + clic sur un objet pour le mettre dans un champ de BlazonGuild",
  ["Mazmorra"] = "Donjon",
