  ["Mensajeros: %s."] = "Messagers : %s.",
  ["Mensajes"] = "Messages",
  ["Mensajes de esta sesión"] = "Messages de cette session",
  ["Mensajes firmados del líder de la alianza para los maestros (y, si quiere, los capitanes). Salen en Alianza, pestaña «Cartas y avisos»; al marcarlas como leídas, el líder lo ve."] = "Messages signés du chef de l'alliance aux maîtres (et, s'il veut, aux capitaines). Ils apparaissent dans Alliance, onglet «Lettres et avis» ; quand tu les marques comme lues, le chef le voit.",
  ["Mensajes por la hermandad"] = "Messages par la guilde",
  ["Mensajes procesados"] = "Messages traités",
  ["Mi ficha"] = "Ma fiche",
  ["Miembros"] = "Membres",
  ["Miembros con el addon conectados hace poco."] = "Membres avec l'addon connectés récemment.",
  ["Miembros en el nivel máximo."] = "Membres au niveau maximum.",
  ["Miembros nuevos que dicen que los trajo (180 días)."] = "Nouveaux membres qui disent qu'il les a amenés (180 jours).",
  ["Miembros que publican sus profesiones."] = "Membres qui publient leurs métiers.",
  ["Miembros que se han conectado en los últimos 7 días."] = "Membres connectés ces 7 derniers jours.",
  ["Miembros: %s (jefe)%s."] = "Membres : %s (chef)%s.",
  ["Mientras tanto ya funcionan en vivo: Resumen, La hermandad, Raids, Mazmorras y Calendario."] = "En attendant, ceci fonctionne déjà en direct : Résumé, La guilde, Raids, Donjons et Calendrier.",
  ["Minas de la Muerte"] = "Les Mortemines",
  ["Minimizada en %s"] = "Réduite dans %s",
  ["Minimizar"] = "Réduire",
  ["Misiones"] = "Quêtes",
  ["Misiones en grupo"] = "Quêtes de groupe",
  ["Moderación"] = "Modération",
  ["Moderación para los organizadores, con avisos y casos que decide el maestro."] = "Modération pour les organisateurs, avec avertissements et dossiers que le maître de guilde décide.",
  ["Moderar"] = "Modérer",
  ["Moderar a %s"] = "Modérer %s",
  ["Modo capturas"] = "Mode captures",
  ["Modo capturas (/bg capturas, o «Capturas» en Administración): una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para enseñar BlazonGuild con todas las pantallas llenas. No sale nada de tu juego."] = "Mode captures (/bg capturas, ou «Captures» dans Administration) : une guilde d'exemple aux noms inventés, sur ton écran seulement, pour montrer BlazonGuild avec tous les écrans remplis. Rien ne sort de ton jeu.",
  ["Modo capturas: una hermandad de ejemplo"] = "Mode captures : une guilde d'exemple",
  ["Modo mando"] = "Mode manette",
  ["Monasterio Escarlata"] = "Monastère Écarlate",
  ["Montaña Roca Negra"] = "Mont Rochenoire",
  ["Montañas de Alterac"] = "Montagnes d'Alterac",
  ["Monte Hyjal"] = "Mont Hyjal",
  ["Mostrar a tu hermandad qué personajes son tuyos"] = "Montrer à ta guilde quels personnages sont les tiens",
  ["Mostrarlos"] = "Les montrer",
  ["Mostrarme conectado"] = "Me montrer connecté",
  ["Muertes con honor y actividad JcJ de cada miembro y por clase."] = "Victoires honorables et activité JcJ de chaque membre et par classe.",
  ["Muertes que ha causado: %s%s. Última víctima: %s."] = "Morts qu'il a causées : %s%s. Dernière victime : %s.",
  ["Muñecas"] = "Poignets",
  ["Más tarde"] = "Plus tard",
  ["Nada"] = "Rien",
  ["Nada en las próximas dos semanas: ni raids de BlazonGuild ni eventos en el calendario del juego. Las raids que cree cualquier miembro en Raids aparecerán aquí."] = "Rien dans les deux prochaines semaines : ni raids BlazonGuild ni événements dans le calendrier du jeu. Les raids que crée n'importe quel membre dans Raids apparaîtront ici.",
  ["Nadie"] = "Personne",
  ["Nadie (acepta la privacidad para aparecer)"] = "Personne (accepte la confidentialité pour apparaître)",
  ["Nadie ahora. Las peticiones las ven los oficiales."] = "Personne pour l'instant. Les officiers voient les demandes.",
  ["Nadie ahora. Las peticiones llegan mientras estás conectado; «Invitar» manda la invitación del juego."] = "Personne pour l'instant. Les demandes arrivent pendant que tu es connecté ; «Inviter» envoie l'invitation du jeu.",
  ["Nadie coincide con la búsqueda."] = "Personne ne correspond à la recherche.",
  ["Nadie comparte ahora su posición. Cada uno lo enciende con «Compartir mi posición»."] = "Personne ne partage sa position en ce moment. Chacun l'active avec «Partager ma position».",
  ["Nadie con recompensa. Cuando alguien de la otra facción mate a un miembro fuera de mazmorras, aparecerá aquí por sí solo."] = "Personne avec une prime. Quand quelqu'un de l'autre faction tuera un membre hors des donjons, il apparaîtra ici tout seul.",
  ["Nadie conectado ahora mismo."] = "Personne de connecté en ce moment.",
  ["Nadie de la hermandad se llama así. Borra lo escrito para ver a todos."] = "Personne dans la guilde ne s'appelle ainsi. Efface ce que tu as écrit pour voir tout le monde.",
  ["Nadie de la lista sabe hacer «%s». En «Encargos» puedes pedirlo a quien sepa."] = "Personne de la liste ne sait faire «%s». Dans «Commandes», tu peux le demander à qui sait le faire.",
  ["Nadie de «%s» conectado ahora, o el nombre no es exacto."] = "Personne de «%s» connecté maintenant, ou le nom n'est pas exact.",
  ["Nadie elegido"] = "Personne de choisi",
  ["Nadie en la hermandad."] = "Personne dans la guilde.",
  ["Nadie en reserva."] = "Personne en réserve.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán con BlazonGuild las hermandades de este canal."] = "Personne n'a encore écrit ici. Commence : les guildes de ce canal le liront avec BlazonGuild.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán los miembros con BlazonGuild."] = "Personne n'a encore écrit ici. Commence : les membres avec BlazonGuild le liront.",
  ["Nadie ha levantado bandera. Levanta la tuya arriba y la hermandad sabrá que buscas grupo."] = "Personne n'a levé de drapeau. Lève le tien en haut et la guilde saura que tu cherches un groupe.",
  ["Nadie lo ha visto todavía."] = "Personne ne l'a encore vu.",
  ["Nadie lo tenía."] = "Personne ne l'avait.",
  ["Nadie lo tenía. Mañana, más boletos gratis."] = "Personne ne l'avait. Demain, d'autres billets gratuits.",
  ["Nadie más conectado ahora mismo."] = "Personne d'autre de connecté en ce moment.",
  ["Nadie más de la hermandad está conectado ahora."] = "Personne d'autre de la guilde n'est connecté en ce moment.",
  ["Nadie más está conectado ahora."] = "Personne d'autre n'est connecté maintenant.",
  ["Nadie te ha retado ahora. Cuando alguien lo haga, te sale aquí con «Aceptar» y «No».\n\nCómo se reta: pulsa «Retar» junto a alguien de la lista (tiene que estar conectado y con BlazonGuild). Si acepta, os avisamos a los dos.\n\nEl duelo lo empezáis desde el juego (clic derecho en su retrato, «Duelo»). Retar no es obligatorio: cualquier duelo entre dos de la hermandad con BlazonGuild cuenta."] = "Personne ne t'a défié pour l'instant. Quand quelqu'un le fera, cela apparaîtra ici avec «Accepter» et «Non».\n\nComment défier : appuie sur «Défier» à côté de quelqu'un de la liste (il doit être connecté et avoir BlazonGuild). S'il accepte, on vous prévient tous les deux.\n\nLe duel, vous le lancez depuis le jeu (clic droit sur son portrait, «Duel»). Défier n'est pas obligatoire : tout duel entre deux membres de la guilde avec BlazonGuild compte.",
  ["Nadie tiene puntos apuntados."] = "Personne n'a de points notés.",
  ["Nadie todavía"] = "Personne pour l'instant",
  ["Nadie. El líder puede ocultar a un jugador o a una hermandad en los chats comunes durante un tiempo."] = "Personne. Le chef peut masquer un joueur ou une guilde dans les discussions communes pendant un temps.",
  ["Naxxramas"] = "Naxxramas",
  ["Necesitas estar en una hermandad."] = "Tu dois être dans une guilde.",
  ["Ninguna"] = "Aucune",
  ["Ninguna encuesta abierta. Cualquiera puede preguntar a la hermandad: qué banda hacer, a qué hora quedar…"] = "Aucun sondage ouvert. N'importe qui peut demander à la guilde : quel raid faire, à quelle heure se retrouver…",
  ["Ninguna. Cuando otra hermandad os invite, aparecerá aquí y vuestro maestro decidirá."] = "Aucune. Quand une autre guilde vous invitera, cela apparaîtra ici et votre maître de guilde décidera.",
  ["Ninguno"] = "Aucun",
  ["Ninguno en esta versión"] = "Aucune dans cette version",
  ["Ningún botón se sale de su panel: ahora lo comprueban las pruebas en todas las pantallas."] = "Aucun bouton ne dépasse de son panneau : les tests le vérifient maintenant sur tous les écrans.",
  ["Ningún organizador con BlazonGuild está conectado ahora. Prueba más tarde."] = "Aucun organisateur avec BlazonGuild n'est connecté maintenant. Réessaie plus tard.",
  ["Nivel"] = "Niveau",
