  ["Nivel y logros en vivo del juego; equipo y JcJ, de los miembros con el addon y de la web."] = "Niveau et hauts faits en direct du jeu ; équipement et JcJ, des membres avec l'addon et du site.",
  ["Niveles en vivo del juego y raids de BlazonGuild."] = "Niveaux en direct du jeu et raids BlazonGuild.",
  ["Niveles en vivo del juego; los grupos se comparten entre los miembros con el addon y con la web."] = "Niveaux en direct du jeu ; les groupes sont partagés entre les membres avec l'addon et avec le site.",
  ["No"] = "Non",
  ["No aceptar peticiones de capa"] = "Ne pas accepter les demandes de couche",
  ["No compartes tu posición."] = "Tu ne partages pas ta position.",
  ["No cuenta para la Arena: %s no tiene BlazonGuild (el combate lo apunta el addon de quien pierde)."] = "Ne compte pas pour l'Arène : %s n'a pas BlazonGuild (c'est l'addon du perdant qui note le combat).",
  ["No cuenta para la Arena: no es de tu hermandad."] = "Ne compte pas pour l'Arène : il n'est pas de ta guilde.",
  ["No es de tu hermandad."] = "Il n'est pas de ta guilde.",
