  ["No estás en ninguna hermandad."] = "Tu n'es dans aucune guilde.",
  ["No hay campañas. Una campaña junta oro para algo concreto (por ejemplo, 100 de oro para pociones de banda) y enseña cuánto falta."] = "Aucune campagne. Une campagne réunit de l'or pour quelque chose de précis (par exemple 100 or pour des potions de raid) et montre ce qui manque.",
  ["No hay cuota semanal. %s"] = "Pas de cotisation hebdomadaire. %s",
  ["No hay encargos. Pide un objeto a un artesano (o a quien sepa hacerlo): te avisamos cuando lo tome y cuando esté hecho."] = "Aucune commande. Demande un objet à un artisan (ou à qui sait le faire) : on te prévient quand il la prend et quand c'est fait.",
  ["No hay grupos abiertos ahora. Crea uno y tu hermandad podrá apuntarse por rol desde el juego."] = "Aucun groupe ouvert pour l'instant. Crées-en un et ta guilde pourra s'inscrire par rôle depuis le jeu.",
  ["No hay nada que elegir ahora."] = "Il n'y a rien à choisir pour l'instant.",
  ["No hay operaciones planeadas."] = "Aucune opération prévue.",
  ["No hay operaciones. Las planean los organizadores y los jefes de escuadra; cuando haya una, te avisamos y respondes desde aquí."] = "Aucune opération. Les organisateurs et les chefs d'escouade les planifient ; quand il y en aura une, on te prévient et tu réponds d'ici.",
  ["No hay operaciones. Planea una: qué se hace, cuándo, dónde y qué escuadras van. Cada uno responde «Voy», «Reserva» o «No puedo»."] = "Aucune opération. Planifies-en une : quoi, quand, où et quelles escouades y vont. Chacun répond «J'y vais», «Réserve» ou «Je ne peux pas».",
  ["No hay sitio"] = "Pas de place",
  ["No llegaste a la capa de %s. Puedes intentarlo de nuevo."] = "Tu n'es pas arrivé sur la couche de %s. Tu peux réessayer.",
  ["No lleva tabardo."] = "Ne porte pas de tabard.",
  ["No lo comparte. Pulsa «Ver su equipo»: si está cerca, lo inspeccionas; si está lejos y tiene BlazonGuild, se lo pedimos.%s"] = "Il ne le partage pas. Appuie sur «Voir son équipement» : s'il est près, tu l'inspectes ; s'il est loin et a BlazonGuild, on le lui demande.%s",
  ["No lo comparte. Si lo tienes cerca (tu objetivo, el ratón encima o en tu grupo), pulsa «Inspeccionar»: lo verás tú, sin enviarlo a nadie.%s"] = "Il ne le partage pas. S'il est près de toi (ta cible, sous la souris ou dans ton groupe), clique sur «Inspecter» : tu le verras, sans l'envoyer à personne.%s",
  ["No molestar"] = "Ne pas déranger",
  ["No mostrarlos"] = "Ne pas les montrer",
