  ["Notas de botín"] = "Notes de butin",
  ["Notas de botín para los organizadores (a quién se dio qué y por qué), con puntos opcionales a mano. Sin pujas ni oro."] = "Notes de butin pour les organisateurs (qui a reçu quoi et pourquoi), avec des points facultatifs à la main. Sans enchères ni or.",
  ["Novedades de BlazonGuild %s"] = "Nouveautés de BlazonGuild %s",
  ["Nueva Armería: el equipo de cada uno, ranura a ranura, si lo comparte (pulsa «Compartir mi equipo»), o si lo inspeccionas tú de cerca."] = "Nouvelle Armurerie : l'équipement de chacun, emplacement par emplacement, s'il le partage (clique sur «Partager mon équipement»), ou si tu l'inspectes de près.",
  ["Nueva Sala de guerra: escuadras con su jefe y su propio chat."] = "Nouvelle Salle de guerre : escouades avec leur chef et leur propre chat.",
  ["Nueva campaña"] = "Nouvelle campagne",
  ["Nueva clave"] = "Nouvelle clé",
