  ["Nueva operación"] = "Nouvelle opération",
  ["Nueva raid"] = "Nouveau raid",
  ["Nueva raid: %s"] = "Nouveau raid : %s",
  ["Nueva sala"] = "Nouveau salon",
  ["Nueva sección Alianza: une tu hermandad con otras (lo deciden los maestros)."] = "Nouvelle section Alliance : unis ta guilde à d'autres (les maîtres décident).",
  ["Nueva sección Arena: duelos entre miembros con su clasificación. El resultado lo lee el propio juego."] = "Nouvelle section Arène : duels entre membres avec leur classement. Le jeu lui-même lit le résultat.",
  ["Nueva sección Artesanía y botín: al abrir tu profesión, puedes publicarla para tu hermandad."] = "Nouvelle section Artisanat et butin : en ouvrant ton métier, tu peux le publier pour ta guilde.",
  ["Nueva sección Chat: el chat de hermandad con más espacio y salas como Sanadores o Comercio."] = "Nouvelle section Chat : le chat de guilde avec plus de place et des salons comme Soigneurs ou Commerce.",
  ["Nueva sección Mapa: cuántos compañeros hay en cada zona y quiénes son."] = "Nouvelle section Carte : combien de compagnons sont dans chaque zone et qui ils sont.",
  ["Nueva sección Reclutamiento: la ficha pública de la hermandad, que escriben los oficiales."] = "Nouvelle section Recrutement : la fiche publique de la guilde, rédigée par les officiers.",
  ["Nueva sección Tablón: anuncios, encuestas, turnos de palabra, la crónica y el resumen de la semana."] = "Nouvelle section Tableau : annonces, sondages, tours de parole, la chronique et le résumé de la semaine.",
  ["Nueva sección Tesorería: el libro de la hermandad se apunta solo cuando das oro a un tesorero (comercio o correo)."] = "Nouvelle section Trésorerie : le registre de la guilde se remplit tout seul quand tu donnes de l'or à un trésorier (échange ou courrier).",
  ["Nueva sección «Se busca»: quien de la otra facción mate a uno de los vuestros fuera de mazmorras entra en la lista con su recompensa."] = "Nouvelle section «Recherchés» : celui de l'autre faction qui tue l'un des vôtres hors des donjons entre dans la liste avec sa prime.",
  ["Nueva temporada"] = "Nouvelle saison",
  ["Nuevo"] = "Nouveau",
  ["Nuevo JcE: quién tiene nivel para cada banda, los jefes que lleva derrotados la hermandad (se apuntan solos) y las últimas raids."] = "Nouveau JcE : qui a le niveau pour chaque raid, les boss que la guilde a vaincus (notés tout seuls) et les derniers raids.",
  ["Nuevo anuncio"] = "Nouvelle annonce",
  ["Nuevo botón redondo en el minimapa: un clic abre o cierra BlazonGuild; arrástralo para moverlo."] = "Nouveau bouton rond sur la minicarte : un clic ouvre ou ferme BlazonGuild ; glisse-le pour le déplacer.",
  ["Nuevo botón «?» arriba: «Cómo funciona», una guía corta y con ejemplos de cada sección complicada."] = "Nouveau bouton «?» en haut : «Comment ça marche», un guide court avec des exemples pour chaque section compliquée.",
  ["Nuevo encargo"] = "Nouvelle commande",
  ["Nuevo honor en Rankings: Campeón de la Arena. Y arreglado: algunos botones salían sin texto."] = "Nouvel honneur dans Classements : Champion de l'Arène. Et corrigé : certains boutons n'affichaient pas de texte.",
  ["Nuevo líder de la alianza"] = "Nouveau chef de l'alliance",
  ["Nuevo torneo o velada"] = "Nouveau tournoi ou nouvelle soirée",
  ["Nunca se comparten tu BattleTag ni tu posición en el mapa sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Ton BattleTag et ta position sur la carte ne sont jamais partagés sans que tu les acceptes à part, une chose à la fois. Si tu refuses, l'addon te montre toujours ta guilde, mais n'envoie rien.",
  ["Nunca se comparten tu posición en el mapa, tu equipo, tus otros personajes, tu BattleTag ni dónde ves a enemigos sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Ta position sur la carte, ton équipement, tes autres personnages, ton BattleTag et l'endroit où tu vois des ennemis ne sont jamais partagés sans que tu l'acceptes à part, une chose à la fois. Si tu n'acceptes pas, l'addon te montre toujours ta guilde, mais n'envoie rien.",
  ["Nunca se han enfrentado"] = "Jamais affrontés",
  ["Núcleo de Magma"] = "Cœur du Magma",
  ["Núcleo de Magma, Guarida Alanegra, Zul'Gurub, Ahn'Qiraj y Naxxramas ya no salen para elegir: no están en Forever. Una raid antigua que las usara se sigue viendo."] = "Cœur du Magma, Repaire de l'Aile noire, Zul'Gurub, Ahn'Qiraj et Naxxramas ne sont plus proposés : ils ne sont pas dans Forever. Un ancien raid qui les utilisait s'affiche toujours.",
