  ["Todavía no ha escrito nada sobre sí."] = "N'a encore rien écrit sur lui.",
  ["Todavía no has escrito nada. Pulsa «Editar mi ficha»."] = "Tu n'as encore rien écrit. Appuie sur «Modifier ma fiche».",
  ["Todavía no hay mensajes en esta sesión. Lo que se diga en el chat de hermandad aparecerá aquí."] = "Pas encore de messages cette session. Ce qui se dira dans le chat de guilde apparaîtra ici.",
  ["Todavía no hay raids programadas en %s."] = "Pas encore de raid programmé dans %s.",
  ["Todos"] = "Tous",
  ["Todos empiezan con %s puntos. Ganar a alguien mejor que tú da más puntos; a alguien de más nivel, también."] = "Tout le monde commence avec %s points. Battre quelqu'un de meilleur que toi rapporte plus ; quelqu'un de plus haut niveau aussi.",
  ["Todos empiezan con 1500. Ganar a alguien mejor da más puntos. Por ejemplo, en tus primeros combates y con el mismo nivel: ganar a uno de 1600 da unos 26; a uno de 1400, unos 14."] = "Tout le monde commence à 1500. Battre quelqu'un de meilleur rapporte plus. Par exemple, dans tes premiers combats et au même niveau : battre quelqu'un à 1600 rapporte environ 26 ; quelqu'un à 1400, environ 14.",
  ["Todos empiezan de cero. ¡Suerte!"] = "Tout le monde repart de zéro. Bonne chance !",
  ["Todos los apuntados tienen grupo."] = "Tous les inscrits ont un groupe.",
  ["Todos los mensajes de la alianza llevan una marca hecha con su clave. Cámbiala si crees que la conoce alguien de fuera."] = "Tous les messages de l'alliance portent une marque faite avec sa clé. Change-la si tu penses que quelqu'un de l'extérieur la connaît.",
  ["Todos ven los grupos; los mueven el líder de la raid, quien la creó y los oficiales."] = "Tout le monde voit les groupes ; le chef du raid, celui qui l'a créé et les officiers les déplacent.",
  ["Todos vuelven a empezar con %s puntos."] = "Tout le monde repart avec %s points.",
  ["Torneo"] = "Tournoi",
  ["Torneo, %s"] = "Tournoi, %s",
  ["Torneo: %s"] = "Tournoi : %s",
  ["Torneo: cada uno se apunta; al sortear sale el cuadro eliminatorio."] = "Tournoi : chacun s'inscrit ; au tirage apparaît le tableau à élimination directe.",
  ["Torneos"] = "Tournois",
  ["Torneos y veladas"] = "Tournois et soirées",
  ["Traerla"] = "L'apporter",
  ["Tres iguales: la cara × 100 (tres 4 = 400); tres 1 = 1000. Cada dado igual de más lo dobla."] = "Trois identiques : la face × 100 (trois 4 = 400) ; trois 1 = 1000. Chaque dé identique de plus double.",
  ["Tu addon apunta solo lo tuyo, con el resumen de muerte y tu golpe final."] = "Ton addon ne note que les tiens, avec le récapitulatif de mort et ton coup fatal.",
  ["Tu bandera en el tablón"] = "Ton drapeau au tableau",
  ["Tu equipo y su nivel"] = "Ton équipement et son niveau",
  ["Tu ficha"] = "Ta fiche",
  ["Tu firma aún no está en la alianza. La añade vuestro maestro la próxima vez que se conecte."] = "Ta signature n'est pas encore dans l'alliance. Votre maître de guilde l'ajoutera à sa prochaine connexion.",
  ["Tu grupo"] = "Ton groupe",
  ["Tu grupo: %s"] = "Ton groupe : %s",
  ["Tu hermandad"] = "Ta guilde",
  ["Tu hermandad dejará de ver el chat de la alianza y sus salas compartidas. Las demás hermandades siguen juntas."] = "Ta guilde ne verra plus le chat de l'alliance ni ses salons partagés. Les autres guildes restent ensemble.",
  ["Tu hermandad ve lo que llevas puesto en la Armería; se actualiza cuando cambias algo."] = "Ta guilde voit ce que tu portes dans l'Armurerie ; ça se met à jour quand tu changes quelque chose.",
  ["Tu hermandad verá en «Artesanía y botín» lo que sabes fabricar de %s (%s/%s)."] = "Ta guilde verra dans «Artisanat et butin» ce que tu sais fabriquer en %s (%s/%s).",
  ["Tu inscripción"] = "Ton inscription",
  ["Tu mensaje volvió en %d ms. Ningún otro miembro conectado tiene BlazonGuild ahora."] = "Ton message est revenu en %d ms. Aucun autre membre connecté n'a BlazonGuild en ce moment.",
  ["Tu nuevo rango, %s, es de organizador en BlazonGuild. A partir de ahora puedes:"] = "Ton nouveau rang, %s, est un rang d'organisateur dans BlazonGuild. Désormais, tu peux :",
  ["Tu posición en el mapa"] = "Ta position sur la carte",
  ["Tu rol en el grupo"] = "Ton rôle dans le groupe",
  ["Tu rol habitual"] = "Ton rôle habituel",
  ["Tu vista"] = "Ta vue",
  ["Tu voto dice que el maestro de %s lidere la alianza."] = "Ton vote dit que le maître de %s doit diriger l'alliance.",
  ["Tu voto es para %s."] = "Ton vote est pour %s.",
