  ["«%s» ya existe. Ahora invita a otra hermandad."] = "«%s» existe déjà. Invite maintenant une autre guilde.",
  ["«%s» ya no puede leer BlazonGuild."] = "«%s» ne peut plus lire BlazonGuild.",
  ["«%s», %s. El parte queda en la crónica de la hermandad."] = "«%s», %s. Le rapport reste dans la chronique de la guilde.",
  ["«%s»: %s hermandades, en contacto con %s"] = "«%s» : %s guildes, en contact avec %s",
  ["«Cara a cara» pone a dos luchadores uno frente al otro, con su vida en directo si los tienes cerca y quién gana al acabar. Se puede agrandar para retransmitir."] = "Le «Face-à-face» met deux combattants l'un en face de l'autre, avec leur vie en direct s'ils sont près de toi et le gagnant à la fin. On peut l'agrandir pour diffuser.",
  ["«Colocar en la banda» mueve a la gente a sus grupos de verdad cuando la banda ya está formada (líder o ayudante, fuera de combate)."] = "«Placer dans le raid» met les gens dans leurs vrais groupes une fois le raid formé (chef ou assistant, hors combat).",
  ["«Copiar» y luego Ctrl+C: pégalo donde quieras."] = "«Copier» puis Ctrl+C : colle-le où tu veux.",
  ["«Grupos» enseña los grupos de la banda como en el juego. El líder de la raid, quien la creó y los oficiales arrastran a cada uno a su grupo y su fila (o lo pulsan y luego pulsan dónde va)."] = "«Groupes» montre les groupes du raid comme dans le jeu. Le chef du raid, celui qui l'a créé et les officiers glissent chacun dans son groupe et sa ligne (ou cliquent dessus puis là où il va).",
  ["«Invitar confirmados» invita a los que van y están conectados, y convierte el grupo en banda."] = "«Inviter les confirmés» invite ceux qui y vont et sont connectés, et transforme le groupe en raid.",
  ["«Mazmorras» ahora se llama Grupos: también para JcJ, misiones, subir de nivel o farmear."] = "«Donjons» s'appelle maintenant Groupes : aussi pour le JcJ, les quêtes, monter de niveau ou farmer.",
  ["«Retar» le manda tu reto; el duelo lo empezáis desde el juego."] = "«Défier» lui envoie ton défi ; le duel, vous le lancez depuis le jeu.",
  ["«Se busca»"] = "«Recherchés»",
  ["«Ver su ficha» en el menú del botón derecho del juego"] = "«Voir sa fiche» dans le menu du clic droit du jeu",
  ["«Ver un duelo» (o /bg duelo): el cara a cara del duelo de tu objetivo. Y en cada torneo o velada, «Cara a cara del siguiente combate»."] = "«Regarder un duel» (ou /bg duelo) : le face-à-face du duel de ta cible. Et dans chaque tournoi ou soirée, «Face-à-face du prochain combat».",
  ["«¡A las armas!» y «Reunión aquí» para los organizadores, con alerta y marca en el mapa."] = "«Aux armes !» et «Réunion ici» pour les organisateurs, avec alerte et marque sur la carte.",
  ["· Ahora la comparten %s%s"] = "· Maintenant partagée par %s%s",
  ["· Las salas de Sanadores, Tanques, Daño, Comercio y Ayuda se comparten."] = "· Les salons Soigneurs, Tanks, Dégâts, Commerce et Aide sont partagés.",
  ["· Los maestros eligen un líder, que puede llamar a las armas a toda la alianza."] = "· Les maîtres choisissent un chef, qui peut appeler toute l'alliance aux armes.",
  ["· Los oficiales de todas tienen su canal, y los maestros el suyo."] = "· Les officiers de toutes ont leur canal, et les maîtres le leur.",
  ["· Quien la comparte sale como un punto de su color de clase en el mapa del mundo (tecla M) de sus compañeros con BlazonGuild."] = "· Celui qui la partage apparaît comme un point de sa couleur de classe sur la carte du monde (touche M) de ses compagnons avec BlazonGuild.",
  ["· Solo tu hermandad; nunca dentro de mazmorras. Tú no ves tu punto: el juego ya te marca."] = "· Seulement ta guilde ; jamais dans les donjons. Tu ne vois pas ton propre point : le jeu te marque déjà.",
  ["· Un chat común: una pestaña para toda la alianza y otra para cada hermandad hermana."] = "· Un chat commun : un onglet pour toute l'alliance et un autre pour chaque guilde sœur.",
